j:jelly.g2:evaluate:
var updateChannels = [];
var updateChannelsGr = new GlideRecord('comm_channel_config');
updateChannelsGr.addActiveQuery();
updateChannelsGr.addQuery('classification', 'update');
updateChannelsGr.query();
while (updateChannelsGr.next()) {
	updateChannels.push(updateChannelsGr.getDisplayValue('type'));
}
updateChannels;

var communicationManagementUtils = new sn_comm_management.CommunicationManagementUtil();
var incidentAlertTasksWithCommunication = [];
var incidentAlertTaskGr = new GlideRecordSecure('incident_alert_task');
incidentAlertTaskGr.addQuery('incident_alert', jelly.jvar_sys_id);
incidentAlertTaskGr.orderBy('order');
incidentAlertTaskGr.query();

while(incidentAlertTaskGr.next()) {
	var commChannelGr = new GlideRecord('comm_channel');
	commChannelGr.addQuery('comm_channel_config.classification', 'IN', 'update');
	commChannelGr.addQuery('comm_task', incidentAlertTaskGr.getUniqueValue());
	commChannelGr.query();
	if (commChannelGr.hasNext()) {
		var incidentAlertTask = {};
		incidentAlertTask.sys_id = incidentAlertTaskGr.getUniqueValue();
		incidentAlertTask.g_scratchpad = {};
		incidentAlertTask.number = incidentAlertTaskGr.getDisplayValue('number');
		incidentAlertTask.priority = incidentAlertTaskGr.getDisplayValue('priority');
		incidentAlertTask.state = incidentAlertTaskGr.getDisplayValue('state');
		incidentAlertTask.assigned_to = incidentAlertTaskGr.getDisplayValue('assigned_to');
		incidentAlertTask.comm_plan = incidentAlertTaskGr.getValue('comm_plan');
		incidentAlertTask.short_description = incidentAlertTaskGr.getDisplayValue('short_description');
		incidentAlertTask.link = incidentAlertTaskGr.getLink(true);
		incidentAlertTask.canSendUpdates = communicationManagementUtils.canSendUpdates(incidentAlertTaskGr, true)
		incidentAlertTasksWithCommunication.push(incidentAlertTask);
	}
}
incidentAlertTasksWithCommunication;

var labels = {};
var gr = new GlideRecord('incident_alert_task');
gr.newRecord();
labels.number = gr.number.getLabel();
labels.priority = gr.priority.getLabel();
labels.state = gr.state.getLabel();
labels.assigned_to = gr.assigned_to.getLabel();
labels.short_description = gr.short_description.getLabel();
labels;

j:jelly.script:
var incidentAlertTasksWithCommunication = [];

	incidentAlertTasksWithCommunication = JSON.parse("$[jvar_incident_alert_tasks_with_communication_string]");


	incidentAlertTasksWithCommunication = JSON.parse("$[JS: jvar_incident_alert_tasks_with_communication_string]");

function sendUpdates(sys_id) {
var incidentAlertTask = getIncidentAlertTaskWithCommunication(sys_id);
	try {
		var ga = new GlideAjax('sn_comm_management.CommunicationManagementUtilAjaxSNC');
		ga.addParam('sysparm_name', 'getCommTaskSourceTable');
		ga.addParam('sysparm_comm_task', incidentAlertTask.sys_id);
		ga.getXML(function(response) {
			var sourceTable = response.responseXML.documentElement.getAttribute("answer");
			if(sourceTable) {
				var dialog = getDefaultGlideModal("task_communication", incidentAlertTask.short_description, 800, true);
				dialog.on('beforeclose', function(event) {
					var reload = dialog.getPreference('reload');
					if(reload)
						location.reload();
				});
				dialog.renderIframe("$task_communication.do?sysparm_stack=no${AMP}amp;sysparm_sys_id=" + sys_id + "${AMP}amp;sysparm_table=" + sourceTable);
			}
		});
	}
	catch(err) {
		console.log(err);
	}
}

function getDefaultGlideModal(name, title, width, flexiableHeight) {
	if (!name)
		return;
	var modal = new GlideModal(name);
	modal.setTitle(title);
	modal.setWidth(width ? width : 1200);
	if(!flexiableHeight)
		modal.setAutoFullHeight(true);
	return modal;
}
function getIncidentAlertTaskWithCommunication(incidentAlertTaskSysId) {
	var incidentAlertTask;
	for (i=0;i${AMP}lt;incidentAlertTasksWithCommunication.length;i++) {
		incidentAlertTask = incidentAlertTasksWithCommunication[i];
		if (incidentAlertTask.sys_id == incidentAlertTaskSysId) {
			break;
		}
	}
	return incidentAlertTask;
}
